import {
  HttpErrorResponse,
  HttpHandlerFn,
  HttpInterceptorFn,
  HttpRequest,
} from '@angular/common/http';
import { inject } from '@angular/core';
import { Router } from '@angular/router';
import { MessageService } from 'primeng/api';
import {
  catchError,
  switchMap,
  filter,
  take,
  throwError,
  Observable,
} from 'rxjs';
import { AuthService } from '../services/auth.service';

export const authInterceptor: HttpInterceptorFn = (
  req: HttpRequest<unknown>,
  next: HttpHandlerFn
) => {
  const router = inject(Router);
  const messageService = inject(MessageService);
  const authService = inject(AuthService);

  // Skip adding auth header for login and refresh token requests
  const isAuthRequest =
    req.url.includes('/api/admin/auth/login') ||
    req.url.includes('/api/admin/auth/refresh-token');

  // Clone the request and add the authorization header if a token is available
  let authReq = req;
  const token = authService.getAccessToken();

  if (token && !isAuthRequest) {
    authReq = req.clone({
      headers: req.headers.set('Authorization', `Bearer ${token}`),
    });
  }

  return next(authReq).pipe(
    catchError((error: HttpErrorResponse) => {
      // Handle 401 Unauthorized errors
      if (error.status === 401) {
        // Try to refresh the token if it's not a refresh token request that failed
        if (!isAuthRequest) {
          return handleUnauthorizedError(
            authReq,
            next,
            error,
            authService,
            router,
            messageService
          );
        } else {
          // If refresh token request fails, log the user out and redirect to login
          return logoutAndRedirect(error, authService, router, messageService);
        }
      }

      // Propagate other errors
      return throwError(() => error);
    })
  );
};

/**
 * Handle 401 unauthorized errors by attempting to refresh the token
 */
function handleUnauthorizedError(
  request: HttpRequest<unknown>,
  next: HttpHandlerFn,
  error: HttpErrorResponse,
  authService: AuthService,
  router: Router,
  messageService: MessageService
): Observable<any> {
  // Check if token refresh is already in progress
  if (!authService.isRefreshingTokenInProgress()) {
    // Start refreshing token
    authService.setRefreshingToken(true);
    // Reset the refresh token subject to null
    authService.resetRefreshTokenSubject();

    // Call the token refresh endpoint
    return authService.refreshToken().pipe(
      // Switch to new observable after token refresh completes
      switchMap(() => {
        // Mark token refresh as complete
        authService.setRefreshingToken(false);

        // Retry the failed request with the new token
        const newToken = authService.getAccessToken();
        if (newToken) {
          request = request.clone({
            headers: request.headers.set('Authorization', `Bearer ${newToken}`),
          });
        }
        return next(request);
      }),
      // Handle errors during token refresh
      catchError((refreshError) => {
        return logoutAndRedirect(
          refreshError,
          authService,
          router,
          messageService
        );
      })
    );
  } else {
    // Wait for the token refresh to complete and retry the request
    return authService.getRefreshTokenSubject().pipe(
      filter((token) => token !== null),
      take(1),
      switchMap((token) => {
        // Clone the request with the new token
        const newReq = request.clone({
          headers: request.headers.set('Authorization', `Bearer ${token}`),
        });
        // Retry the request
        return next(newReq);
      })
    );
  }
}

/**
 * Log the user out and redirect to the login page
 */
function logoutAndRedirect(
  error: any,
  authService: AuthService,
  router: Router,
  messageService: MessageService
): Observable<never> {
  // Reset the token refresh status
  authService.setRefreshingToken(false);

  // Clear authentication tokens
  authService.clearTokens();

  // Display an error message
  messageService.add({
    severity: 'error',
    summary: 'Session Expired',
    detail: 'Your session has expired. Please log in again.',
  });

  // Redirect to login page
  router.navigate(['/auth/login']);

  // Propagate the error
  return throwError(() => error);
}
