import { Routes } from '@angular/router';
import { AppLayoutComponent } from './layout/app.layout.component';
import { HomeComponent } from './core/components/home/home.component';
// import { EditorIndexComponent } from './core/components/editor-index/editor-index.component';

export const routes: Routes = [
  {
    path: '',
    component: AppLayoutComponent,
    children: [
      { path: '', component: HomeComponent },
      {
        path: 'products',
        loadChildren: () =>
          import('./features/products/products.module').then(
            (m) => m.ProductsModule
          ),
      },
      {
        path: 'order',
        loadChildren: () =>
          import('./features/order/order.module').then((m) => m.OrderModule),
      },
      {
        path: 'contents',
        loadChildren: () =>
          import('./features/contents/contents.module').then(
            (m) => m.ContentsModule
          ),
      },
      {
        path: 'settings',
        loadChildren: () =>
          import('./features/settings/settings.module').then(
            (m) => m.SettingsModule
          ),
      },
      {
        path: 'accounts',
        loadChildren: () =>
          import('./features/accounts/accounts.module').then(
            (m) => m.AccountsModule
          ),
      },
      {
        path: 'users',
        loadChildren: () =>
          import('./features/users/users.module').then((m) => m.UsersModule),
      },
      {
        path: 'menus',
        loadChildren: () =>
          import('./features/menus/menus.module').then((m) => m.MenusModule),
      },
    ],
  },
  {
    path: 'auth',
    loadChildren: () =>
      import('./features/auth/auth.module').then((m) => m.AuthModule),
  },
  // {
  //   path: 'editor',
  //   component: EditorIndexComponent,
  // },
];
